-- Configure only the newly created Minh An's task/minimal prompt files.
BEGIN;
SET LOCAL lock_timeout='5s';
INSERT INTO agent_context_files (agent_id, tenant_id, file_name, content)
SELECT id, tenant_id, 'AGENTS_CORE.md', convert_from(decode('','base64'),'UTF8')
FROM agents WHERE id='01a19038-5f68-7d48-b0cc-5bac240e2a40'::uuid
  AND agent_key='minh-an' AND tenant_id='0193a5b0-7000-7000-8000-000000000001'::uuid
ON CONFLICT (agent_id,file_name) DO UPDATE SET content=EXCLUDED.content,updated_at=NOW();
INSERT INTO agent_context_files (agent_id, tenant_id, file_name, content)
SELECT id, tenant_id, 'AGENTS_TASK.md', convert_from(decode('','base64'),'UTF8')
FROM agents WHERE id='01a19038-5f68-7d48-b0cc-5bac240e2a40'::uuid
  AND agent_key='minh-an' AND tenant_id='0193a5b0-7000-7000-8000-000000000001'::uuid
ON CONFLICT (agent_id,file_name) DO UPDATE SET content=EXCLUDED.content,updated_at=NOW();
COMMIT;
